module Dnsruby
  #  RFC 7873 DNS Cookie.
  #
  #  A COOKIE option (EDNS option code 10) carries an 8-byte client cookie
  #  and an optional server cookie of 8 to 32 bytes.
  #
  #  The client cookie is generated by the deployer (see
  #  PacketSender#client_cookie_generator=) - typically as a hash of the
  #  client address, the server address and a secret known only to the
  #  client. The server cookie is learned from the server and remembered
  #  per-server by the PacketSender.
  #
  #  This class performs strict encoding and decoding of the option data :
  #  any other length combination is rejected.
  class Cookie
    #  The EDNS option code for COOKIE (RFC 7873 section 3)
    OPTION_CODE = 10

    #  The client cookie is always exactly 8 bytes
    CLIENT_LENGTH = 8

    #  The server cookie, when present, is 8 to 32 bytes
    MIN_SERVER_LENGTH = 8
    MAX_SERVER_LENGTH = 32

    #  The full option is 8 bytes (client cookie only) or 16 to 40 bytes
    MAX_LENGTH = CLIENT_LENGTH + MAX_SERVER_LENGTH

    attr_reader :client, :server

    #  Create a new Cookie from a client cookie and an optional server
    #  cookie. Raises ArgumentError if either cookie has an invalid length.
    def initialize(client, server = nil)
      unless client && client.length == CLIENT_LENGTH
        raise ArgumentError.new("Client cookie must be exactly #{CLIENT_LENGTH} bytes (got #{client ? client.length : 'nil'})")
      end
      if server && (server.length < MIN_SERVER_LENGTH || server.length > MAX_SERVER_LENGTH)
        raise ArgumentError.new("Server cookie must be #{MIN_SERVER_LENGTH}-#{MAX_SERVER_LENGTH} bytes (got #{server.length})")
      end
      @client = client.dup
      @server = server ? server.dup : nil
    end

    #  Strictly decode the wire format of a COOKIE option.
    #  Raises DecodeError if the data length is not 8 (client cookie only)
    #  or 16 to 40 (client and server cookie) bytes.
    def self.decode(data)
      length = data ? data.length : 0
      valid = (length == CLIENT_LENGTH) ||
          (length >= CLIENT_LENGTH + MIN_SERVER_LENGTH && length <= MAX_LENGTH)
      unless valid
        raise DecodeError.new("Invalid COOKIE option length #{length} (must be #{CLIENT_LENGTH} or #{CLIENT_LENGTH + MIN_SERVER_LENGTH}-#{MAX_LENGTH})")
      end
      server = length > CLIENT_LENGTH ? data[CLIENT_LENGTH, length - CLIENT_LENGTH] : nil
      new(data[0, CLIENT_LENGTH], server)
    end

    #  Encode this cookie to the wire format of the COOKIE option data
    def encode
      @server ? @client + @server : @client
    end

    def ==(other)
      other.kind_of?(Cookie) && other.client == @client && other.server == @server
    end

    def to_s
      @server ? (@client + @server).unpack1('H*') : @client.unpack1('H*')
    end
  end
end
